CREATE TABLE public.simulation_templates (id text PRIMARY KEY, data jsonb NOT NULL);
GRANT ALL ON public.simulation_templates TO service_role;
ALTER TABLE public.simulation_templates ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.sites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, template_key text NOT NULL, data jsonb NOT NULL, last_maintenance date, maintenance_months integer NOT NULL DEFAULT 24 CHECK (maintenance_months > 0), panel_manufacturer text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id, template_key));
GRANT SELECT ON public.sites TO authenticated; GRANT ALL ON public.sites TO service_role;
ALTER TABLE public.sites ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_read_site(_site uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.sites s WHERE s.id=_site AND (s.owner_id=auth.uid() OR (public.has_role(auth.uid(),'business') AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=s.owner_id AND p.company_id=auth.uid())))) $$;
CREATE POLICY "Owners and linked businesses read sites" ON public.sites FOR SELECT TO authenticated USING (public.can_read_site(id));
CREATE TABLE public.crews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL, template_key text NOT NULL, data jsonb NOT NULL, UNIQUE(company_id,template_key));
GRANT SELECT ON public.crews TO authenticated; GRANT ALL ON public.crews TO service_role;
ALTER TABLE public.crews ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Businesses read own crews" ON public.crews FOR SELECT TO authenticated USING (company_id=auth.uid() AND public.has_role(auth.uid(),'business'));
CREATE TABLE public.dispatch_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES public.sites(id), reference text NOT NULL, title text NOT NULL, priority text NOT NULL CHECK(priority IN ('High','Medium','Low')), status text NOT NULL DEFAULT 'New' CHECK(status IN ('New','Assigned','En route','Resolved')), crew_id uuid REFERENCES public.crews(id), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(status='New' OR crew_id IS NOT NULL), UNIQUE(site_id,reference));
GRANT SELECT ON public.dispatch_jobs TO authenticated; GRANT UPDATE(status,crew_id) ON public.dispatch_jobs TO authenticated; GRANT ALL ON public.dispatch_jobs TO service_role;
ALTER TABLE public.dispatch_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read visible site jobs" ON public.dispatch_jobs FOR SELECT TO authenticated USING(public.can_read_site(site_id));
CREATE POLICY "Businesses manage visible jobs" ON public.dispatch_jobs FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'business') AND public.can_read_site(site_id)) WITH CHECK(public.has_role(auth.uid(),'business') AND public.can_read_site(site_id) AND (crew_id IS NULL OR EXISTS(SELECT 1 FROM public.crews c WHERE c.id=crew_id AND c.company_id=auth.uid())));
CREATE FUNCTION public.validate_dispatch_change() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.status='Resolved' AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.crew_id IS DISTINCT FROM OLD.crew_id) THEN RAISE EXCEPTION 'Resolved jobs cannot be changed'; END IF; IF NEW.crew_id IS NULL THEN NEW.status:='New'; ELSIF NEW.status='New' THEN NEW.status:='Assigned'; END IF; IF array_position(ARRAY['New','Assigned','En route','Resolved'],NEW.status)>array_position(ARRAY['New','Assigned','En route','Resolved'],OLD.status)+1 THEN RAISE EXCEPTION 'Advance one status at a time'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER validate_dispatch_change BEFORE UPDATE ON public.dispatch_jobs FOR EACH ROW EXECUTE FUNCTION public.validate_dispatch_change();
CREATE TABLE public.site_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES public.sites(id), reference text NOT NULL, data jsonb NOT NULL, status text NOT NULL DEFAULT 'New' CHECK(status IN ('New','Investigating','Scheduled','Resolved')), technician text NOT NULL DEFAULT 'Unassigned', UNIQUE(site_id,reference));
GRANT SELECT ON public.site_alerts TO authenticated; GRANT UPDATE(status,technician) ON public.site_alerts TO authenticated; GRANT ALL ON public.site_alerts TO service_role;
ALTER TABLE public.site_alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read visible alerts" ON public.site_alerts FOR SELECT TO authenticated USING(public.can_read_site(site_id));
CREATE POLICY "Businesses manage visible alerts" ON public.site_alerts FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'business') AND public.can_read_site(site_id)) WITH CHECK(public.has_role(auth.uid(),'business') AND public.can_read_site(site_id));
CREATE TABLE public.account_settings (user_id uuid PRIMARY KEY, data jsonb NOT NULL DEFAULT '{}'::jsonb);
GRANT SELECT,INSERT,UPDATE ON public.account_settings TO authenticated; GRANT ALL ON public.account_settings TO service_role;
ALTER TABLE public.account_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own settings" ON public.account_settings FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, data jsonb NOT NULL, read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.notifications TO authenticated; GRANT UPDATE(read) ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own notifications read" ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "Own notifications add" ON public.notifications FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY "Own notifications mark read" ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE INDEX sites_owner ON public.sites(owner_id); CREATE INDEX jobs_site ON public.dispatch_jobs(site_id); CREATE INDEX alerts_site ON public.site_alerts(site_id); CREATE INDEX notifications_user ON public.notifications(user_id);
CREATE FUNCTION public.provision_account_simulation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bundle jsonb; item jsonb; new_site uuid; mapped_site uuid; mapped_crew uuid; selected_key text; BEGIN SELECT data INTO bundle FROM public.simulation_templates WHERE id='gridpulse-v1'; IF bundle IS NULL THEN RETURN NEW; END IF; selected_key:=bundle->>'homeKey'; FOR item IN SELECT value FROM jsonb_array_elements(bundle->'sites') LOOP IF NEW.role='business' OR item->'site'->>'id'=selected_key THEN INSERT INTO public.sites(owner_id,template_key,data,last_maintenance,panel_manufacturer) VALUES(NEW.user_id,item->'site'->>'id',item->'site',NULLIF(item->>'last','')::date,item->>'panelManufacturer') ON CONFLICT DO NOTHING; END IF; END LOOP; IF NEW.role='business' THEN FOR item IN SELECT value FROM jsonb_array_elements(bundle->'crews') LOOP INSERT INTO public.crews(company_id,template_key,data) VALUES(NEW.user_id,item->>'id',item) ON CONFLICT DO NOTHING; END LOOP; END IF; FOR item IN SELECT value FROM jsonb_array_elements(bundle->'jobs') LOOP SELECT id INTO mapped_site FROM public.sites WHERE owner_id=NEW.user_id AND template_key=item->>'siteId'; IF mapped_site IS NOT NULL THEN SELECT id INTO mapped_crew FROM public.crews WHERE company_id=NEW.user_id AND template_key=item->>'crewId'; INSERT INTO public.dispatch_jobs(site_id,reference,title,priority,status,crew_id) VALUES(mapped_site,item->>'id',item->>'title',item->>'priority',CASE WHEN mapped_crew IS NULL THEN 'New' ELSE item->>'status' END,mapped_crew) ON CONFLICT DO NOTHING; END IF; END LOOP; FOR item IN SELECT value FROM jsonb_array_elements(bundle->'alerts') LOOP SELECT id INTO mapped_site FROM public.sites WHERE owner_id=NEW.user_id AND template_key=item->>'siteId'; IF mapped_site IS NOT NULL THEN INSERT INTO public.site_alerts(site_id,reference,data,status,technician) VALUES(mapped_site,item->>'id',item,item->>'status',item->>'technician') ON CONFLICT DO NOTHING; END IF; END LOOP; INSERT INTO public.account_settings(user_id,data) VALUES(NEW.user_id,bundle->'settings') ON CONFLICT DO NOTHING; FOR item IN SELECT value FROM jsonb_array_elements(bundle->'notifications') LOOP INSERT INTO public.notifications(user_id,data,read) VALUES(NEW.user_id,item,COALESCE((item->>'read')::boolean,false)); END LOOP; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.provision_account_simulation() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER provision_account_simulation AFTER INSERT ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.provision_account_simulation();
COMMENT ON TABLE public.simulation_templates IS 'Explicit simulation catalog; copied once at account creation, never seeded on page load. Not manufacturer telemetry.';
COMMENT ON TABLE public.sites IS 'Persisted installations with stored simulated hourly readings, historical series and service history in data; replace with real device data when connected.';